function send(type:string,data:AnyObj={}){if(!room){toast('Нет соединения с сервером. Проверь, запущен ли сервер.');return;}room.send(type,data);}
function toast(text:string){lastNotice=text;let n=document.querySelector<HTMLDivElement>('.notice');if(!n){n=document.createElement('div');n.className='notice';n.setAttribute('role','status');n.setAttribute('aria-live','polite');document.body.appendChild(n);}n.textContent=text;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{n!.hidden=true;},4800);}
function pct(n:number,d:number){return Math.max(0,Math.min(100,d?100*n/d:0));}
function statCost(stat:string,value:number){const v=Number(value||0);return stat==='defense'?90+Math.floor(v*6):stat==='luck'?150+Math.floor(v*12):stat==='accuracy'?120+Math.floor(v*8):100+Math.floor(v*7);}
function item(id:string):Item|undefined{return items.find(i=>i.id===id);}
function itemIcon(i:Pick<Item,'id'|'kind'|'name'>){const safeId=/^[a-zA-Z0-9_-]+$/.test(i.id)?i.id:'';const fallbackKind=['weapon','armor','amulet','potion','material'].includes(i.kind)?i.kind:'misc';let hash=0;for(let n=0;n<i.id.length;n++)hash=(hash*31+i.id.charCodeAt(n))>>>0;const fallback=`/assets/items/${fallbackKind}-${hash%8}.svg`;return `<span class="item-art-frame" data-item-id="${esc(i.id)}" tabindex="0" role="img" aria-label="${esc(i.name)} — показать описание" title="${esc(i.name)}"><img class="item-art" src="/assets/items/by-id/${safeId}.svg" onerror="this.onerror=null;this.src='${fallback}'" alt="${esc(i.name)}" loading="lazy"></span>`;}
function itemStats(i:Item){return [i.attack?`Атака +${i.attack}`:'',i.defense?`Защита +${i.defense}`:'',i.health?`HP +${i.health}`:'',i.heal?`Лечение ${Math.round(i.heal*100)}%`:'',i.profession?`Профессия: ${i.profession}`:'',i.level>1?`Требуется уровень ${i.level}`:'',i.rarity||''].filter(Boolean).join(' · ');}
function basePage(title:string,subtitle:string,body:string){return `<section class="panel"><h1 class="page-title">${title}</h1><p class="subtitle">${subtitle}</p>${body}</section>`;}
function combatJournalHtml(){
 const current=lastCombatReport||combatHistory[0]||null;
 if(!current)return `<div class="log">Пока боевых записей нет. Выбери зону и отправляйся в поход.</div>`;
 const lines=Array.isArray(current.lines)?current.lines:[];
 const status=current.result==='win'?'Победа':'Отступление';
 const history=combatHistory.slice(0,6).map((r:AnyObj)=>`<div class="combat-history-row"><span class="combat-history-mark ${r.result==='win'?'win':'loss'}">${r.result==='win'?'✓':'↩'}</span><div><strong>${esc(r.enemy||'Противник')}</strong><small>${esc(r.zone||r.mode||'Бой')} · ${r.profession?esc(r.profession)+' · ':''}${new Date(Number(r.at||Date.now())).toLocaleString('ru-RU')}</small></div><span class="combat-history-outcome">${r.result==='win'?'Победа':'Отступление'}</span></div>`).join('');
 return `<section class="combat-journal"><div class="combat-journal-head"><div><span class="eyebrow">БОЕВОЙ ЖУРНАЛ</span><h3>${esc(current.enemy||'Последний бой')}</h3><p>${esc(current.zone||current.mode||'Охота')} · ${esc(current.profession||'Без профессии')} · ${status}</p></div><span class="combat-status ${current.result==='win'?'win':'loss'}">${status}</span></div><div class="combat-metrics"><div><small>Атака</small><strong>${money(current.attack||0)}</strong></div><div><small>Защита</small><strong>${money(current.defense||0)}</strong></div><div><small>Нанесено</small><strong>${money(current.damage||0)}</strong></div><div><small>Получено</small><strong>${money(current.received||0)}</strong></div><div><small>Здоровье</small><strong>${money(current.hpAfter||0)}/${money(current.maxHealth||0)}</strong></div></div><div class="combat-journal-lines">${lines.map((line:string)=>`<div class="combat-journal-line">${esc(line)}</div>`).join('')}</div>${history?`<details class="combat-history"><summary>Последние бои · ${combatHistory.length}</summary>${history}</details>`:''}</section>`;
}
function breadcrumb(){
 const names:Record<string,string>={journal:'Журнал путешественника',world:'События мира',market:'Экономика',tavern:'Городской трактир',effects:'Эффекты',character:'Персонаж',city:'Город',map:'Мир',farm:'Охота',inventory:'Инвентарь',quests:'Задания',clan:'Клан',shop:'Магазин',enhance:'Заточка',gear:'Свойства и наборы',skills:'Навыки',craft:'Ремесло',auction:'Аукцион',pvp:'PvP-арена',guilds:'Боевая гильдия',home:'Мой дом',mail:'Почта',dungeons:'Подземелья',achievements:'Достижения',admin:'Админ-панель'};
 let path:{id:string,label:string}[]=[];
 if(activeTab==='shop'){const cat:Record<string,string>={weapon:'Оружие',armor:'Броня',amulet:'Кольца',material:'Материалы',potion:'Зелья'};path=[{id:'city',label:'Город'},{id:'shop',label:'Магазин'},{id:'shop',label:cat[shopCategory]||'Товары'}];}
 else if(['enhance','gear','craft','guilds','auction'].includes(activeTab)){const parent=activeTab==='guilds'?'city':activeTab==='craft'||activeTab==='enhance'||activeTab==='gear'?'inventory':'city';path=[{id:'city',label:'Город'},{id:parent,label:names[parent]},{id:activeTab,label:names[activeTab]||'Раздел'}];}
 else if(activeTab==='farm'||activeTab==='dungeons'){path=[{id:'map',label:'Мир'},{id:activeTab,label:names[activeTab]}];}
 else if(activeTab==='inventory'||activeTab==='skills'){path=[{id:'character',label:'Персонаж'},{id:activeTab,label:names[activeTab]}];}
 else {path=[{id:activeTab,label:names[activeTab]||'Раздел'}];}
 return `<nav class="breadcrumb" aria-label="Путь по игре">${path.map((part,i)=>i===path.length-1?`<span class="breadcrumb-current" aria-current="page">${esc(part.label)}</span>`:`<button type="button" data-tab="${part.id}" class="breadcrumb-link">${esc(part.label)}</button><span class="breadcrumb-separator" aria-hidden="true">›</span>`).join('')}</nav>`;
}
