function positionItemTooltip(x:number,y:number){const pad=14;const w=itemTooltip.offsetWidth||300;const h=itemTooltip.offsetHeight||160;let left=x+18,top=y+18;if(left+w>window.innerWidth-pad)left=x-w-18;if(top+h>window.innerHeight-pad)top=y-h-18;itemTooltip.style.left=`${Math.max(pad,left)}px`;itemTooltip.style.top=`${Math.max(pad,top)}px`;}
