async function connect(){if(connecting||!authToken){if(!authToken)renderAuth();return;}connecting=true;try{client=new Client(SERVER_HTTP);room=await client.joinOrCreate('my_room',{playerId,sessionToken:authToken});connected=true;connecting=false;if(reconnectTimer){clearTimeout(reconnectTimer);reconnectTimer=null;}player=room.state.player;room.onLeave(()=>{connected=false;connecting=false;pendingActions.clear();if(manualLogout){manualLogout=false;return;}render();if(!reconnectTimer)reconnectTimer=setTimeout(()=>{reconnectTimer=null;connect();},5000);});room.onStateChange(()=>{player=room.state.player;render();});room.onMessage('catalog',(d:any)=>{items=d.items||[];shopItems=d.shopItems||items.filter((i:Item)=>!i.legacy);zones=d.zones||[];expedition=d.expedition||null;neutralCities=d.neutralCities||[];professions=d.professions||{};recipes=d.recipes||[];guildSkills=d.guildSkills||{};cityLocations=d.cityLocations||{};cityNpcs=d.cityNpcs||[];regionEvent=d.regionEvent||null;regionEvents=d.regionEvents||[];bossCatalog=d.bossCatalog||[];raceCityInfo=d.raceCityInfo||{};raceDailyQuests=d.raceDailyQuests||{};rareProperties=d.rareProperties||{};professionSkills=d.professionSkills||{};dungeons=d.dungeons||[];equipmentSets=d.equipmentSets||[];render();});room.onMessage('notice',(d:any)=>{pendingActions.clear();toast(String(d?.text||''));player=room.state.player;render();});room.onMessage('expeditionState',(d:any)=>{expeditionState=d.state||null;expedition=d.branch||expedition;render();});room.onMessage('huntGroupState',(d:any)=>{huntGroup=d.group||null;render();});room.onMessage('huntGroupPlayers',(d:any)=>{huntGroupPlayers=d.players||[];render();});room.onMessage('friendInvite',(d:any)=>{if(window.confirm(`${d.fromName||'Игрок'} предлагает добавить тебя в друзья. Принять?`))send('friendAccept',{fromId:d.fromId});});room.onMessage('friendAccepted',(d:any)=>{toast(`${d.name||'Игрок'} теперь в твоём списке друзей.`);send('huntGroupList');});room.onMessage('huntGroupInvite',(d:any)=>{if(window.confirm(`${d.fromName||'Игрок'} приглашает тебя в охотничью группу. Принять?`))send('huntGroupAccept',{groupId:d.groupId});});room.onMessage('combatHistory',(d:any)=>{combatHistory=Array.isArray(d?.history)?d.history:[];if(!lastCombatReport&&combatHistory.length)lastCombatReport=combatHistory[0];render();});room.onMessage('combatResult',(d:any)=>{lastCombat=String(d?.text||'');lastCombatReport=d?.report||null;activeTab='farm';render();});room.onMessage('pvpResult',(d:any)=>{lastCombat=String(d?.text||'');lastCombatReport=d?.report||null;activeTab='pvp';render();});room.onMessage('clanList',(d:any)=>{clanList=d.clans||[];render();room.send('clanQuests');room.send('clanTerritories');});room.onMessage('pvpList',(d:any)=>{pvpPlayers=d.players||[];pvpMeta={cooldownUntil:Number(d.cooldownUntil||0),offersExpireAt:Number(d.offersExpireAt||0),immunityUntil:Number(d.immunityUntil||0)};pvpRefreshRequestedFor=0;render();});room.onMessage('auctionList',(d:any)=>{auctionLots=d.list||[];render();});room.onMessage('auctionHistory',(d:any)=>{auctionHistory=d.history||[];render();});room.onMessage('marketHistory',(d:any)=>{marketHistory=d.history||[];render();});room.onMessage('dungeonList',(d:any)=>{dungeons=d.dungeons||[];render();});room.onMessage('clanWarList',(d:any)=>{clanWars=d.wars||[];render();});room.onMessage('clanTerritories',(d:any)=>{clanTerritories=d.territories||[];render();});room.onMessage('clanQuests',(d:any)=>{clanQuests=d.quests||[];clanUpgrades=d.upgrades||{barracks:0,treasury:0,banner:0};clanSeason=d.season||[];render();});room.onMessage('craftQueue',(d:any)=>{if(player)player.craftQueue=JSON.stringify(d.jobs||[]);render();});room.onMessage('hello',()=>{connected=true;render();});room.send('getCatalog');room.send('expeditionState');room.send('huntGroupList');room.send('clanList');room.send('pvpList');room.send('auctionList');room.send('auctionHistory');room.send('marketHistory');room.send('dungeonList');room.send('clanWarList');room.send('clanTerritories');room.send('clanQuests');room.send('craftQueue');render();}catch(e){connected=false;connecting=false;try{const check=await fetch(`${SERVER_HTTP}/auth/check`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:authToken})});if(check.status===401){authToken='';localStorage.removeItem(sessionKey);renderAuth();toast('Сессия завершилась. Войди в аккаунт снова.');return;}}catch{}render();toast('Нет соединения с сервером. Повторная попытка через 5 секунд.');console.error(e);if(!reconnectTimer)reconnectTimer=setTimeout(()=>{reconnectTimer=null;connect();},5000);}}
render();if(authToken)connect();else renderAuth();

setInterval(()=>{if(!player)return;const pvpClock=document.querySelector<HTMLElement>('#pvpCooldown');if(pvpClock){const left=Math.max(0,Math.ceil((Number(pvpMeta.cooldownUntil||0)-Date.now())/1000));pvpClock.textContent=left>0?`Следующая атака через ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:pvpPlayers.length?'Можно выбрать одного из четырёх соперников.':'Можно обновить список соперников.';}const pvpShield=document.querySelector<HTMLElement>('#pvpImmunity');if(pvpShield){const left=Math.max(0,Math.ceil((Number(pvpMeta.immunityUntil||0)-Date.now())/1000));pvpShield.textContent=left>0?`🛡️ Твой иммунитет от нападений: ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:'Защита от нападений завершена.';}const pvpReadyAt=Number(pvpMeta.cooldownUntil||pvpMeta.offersExpireAt||0);if(pvpReadyAt>0&&Date.now()>=pvpReadyAt&&pvpRefreshRequestedFor!==pvpReadyAt){pvpRefreshRequestedFor=pvpReadyAt;pvpPlayers=[];send('pvpList');if(activeTab==='pvp')render();}let crossed=false;document.querySelectorAll<HTMLElement>('.timer-row[data-ends-at]').forEach(row=>{const ends=Number(row.dataset.endsAt||0);const left=Math.max(0,Math.ceil((ends-Date.now())/1000));const value=row.querySelector<HTMLElement>('.timer-value');if(value){value.textContent=left>0?`Осталось ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:row.dataset.timerKind==='craft'?'Готово к получению':row.dataset.timerKind==='expedition-search'?'Поиск завершён':'Переход завершён';}if(left===0&&row.dataset.timerKind?.startsWith('expedition-')&&document.querySelector('#expeditionCountdown'))crossed=true;});const expStateNow=parse(player.quests,{}).expedition||expeditionState||{};const expClock=document.querySelector<HTMLElement>('#expeditionCountdown');if(expClock){const sec=Math.max(0,Math.ceil((Number(expStateNow.endsAt||0)-Date.now())/1000));expClock.textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;if(sec===0)crossed=true;}if(crossed)render();},1000);
